using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();
        string inputText = args["rawInput"].ToString();

        // Parse wager
        if (string.IsNullOrEmpty(inputText)) {
            CPH.SendMessage($"@{userName}, usage: !roll20 [wager]. Example: !roll20 50 (min: 10, max: 500)");
            return false;
        }

        int wager;
        if (!int.TryParse(inputText, out wager) || wager < 10 || wager > 500) {
            CPH.SendMessage($"@{userName}, wager must be between 10 and 500 eggs!");
            return false;
        }

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";
        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Check balance
        if (data["users"] == null || data["users"][userId] == null) {
            CPH.SendMessage($"@{userName}, you don't have any eggs! Start chatting to earn some!");
            return false;
        }

        int currentEggs = (int)(data["users"][userId]["eggs"] ?? 0);

        if (currentEggs < wager) {
            CPH.SendMessage($"@{userName}, you don't have enough eggs! You have {currentEggs} eggs.");
            return false;
        }

        // Roll D20
        Random rnd = new Random();
        int roll = rnd.Next(1, 21);

        // Calculate result
        int result = 0;
        string flavor = "";

        if (roll == 1) {
            result = -(wager + wager / 2);
            flavor = "💀 CRITICAL FAIL!";
        } else if (roll >= 2 && roll <= 5) {
            result = -wager;
            flavor = "❌ Miss!";
        } else if (roll >= 6 && roll <= 10) {
            result = -(wager / 2);
            flavor = "😬 Partial Loss";
        } else if (roll >= 11 && roll <= 14) {
            result = 0;
            flavor = "😐 Push";
        } else if (roll >= 15 && roll <= 18) {
            result = wager / 2;
            flavor = "✅ Hit!";
        } else if (roll == 19) {
            result = wager;
            flavor = "🌟 Great Roll!";
        } else if (roll == 20) {
            result = wager * 4 + 100;
            flavor = "💎 CRITICAL SUCCESS!";
        }

        // Update eggs
        int newEggs = Math.Max(0, currentEggs + result);
        data["users"][userId]["eggs"] = newEggs;

        File.WriteAllText(dataPath, data.ToString());

        // Send message
        string resultStr = result > 0 ? $"+{result}" : result.ToString();
        CPH.SendMessage($"🎲 @{userName} rolled a {roll}! {flavor} Result: {resultStr} eggs! Total: {newEggs} 🥚");

        return true;
    }
}
